constexpr int Factorial(int n) {
    return (n <= 1) ? 1 : n * Factorial(n - 1);
}

// Result guaranteed to be evaluated at compile time
constexpr int STATIC_INIT_VAL = Factorial(6); // 720

// Usage in context requiring a constant expression
template<int N>
struct LookupTable {};

// Template argument deduction at compile time
using Table = LookupTable< Factorial(3) >;

// Array size determined at compile time
void use_array() {
    int arr[STATIC_INIT_VAL];
}

// Runtime call still possible if arguments aren't constant
int runtime_call(int x) { return Factorial(x); }

