class VBase {
// Object layout: [vptr | members...]
// VTABLE Layout: [0: f1, 1: f2, 2: ~VBase]
public:
    virtual void f1() {}
    virtual void f2() {}
    virtual ~VBase() = default;
};

class VDerived : public VBase {
// VDerived VTABLE entry 0 points to D::f1
public:
    void f1() override {}
};

// Dispatch: ptr->vptr->vtable[index]->function_address
void invoke_dispatch(VBase* ptr) {
    // Runtime lookup required
    ptr->f1();

    // Constant offset lookup (if known not overridden)
    ptr->f2(); 
}

